using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using OpenAI;

var services = new ServiceCollection();

services.AddLogging(builder => builder.AddConsole().SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(
        modelId: "gpt-4o-mini-2024-07-18",
        apiKey: Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set the OPENAI_API_KEY environment variable.")));

await using var sp = services.BuildServiceProvider();

var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// Define the tools available to the agent
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// Create the research agent
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    },
    loggerFactory);

// Prompt the user for a topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User,
        $"""
        Research the following topic thoroughly: "{topic}"

        Instructions:
        1. Use the web_search tool to find relevant information (perform 2-3 searches with different queries).
        2. Use the save_note tool to save key findings as you go.
        3. After gathering enough information, use the get_notes tool to review your notes.
        4. Provide a comprehensive summary of your findings.
        """),
};

var session = await agent.CreateSessionAsync();

await foreach (var update in agent.RunStreamingAsync(messages, session))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

// --- Tool implementations ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns a list of relevant results.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search API).
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

    return $"""
        Search results for "{query}":
        1. Wikipedia - Overview article covering key aspects of {query}, including history and current developments.
        2. Research Paper (2024) - Recent academic findings related to {query}, highlighting breakthroughs and challenges.
        3. News Article - Latest news coverage about {query}, discussing recent events and public impact.
        4. Expert Blog - In-depth analysis by domain experts on the implications and future directions of {query}.
        """;
}

[Description("Save a research note for later reference.")]
string SaveNote([Description("The note content to save")] string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved successfully. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
    {
        return "No notes saved yet.";
    }

    Console.WriteLine($"  [Tool] Retrieving {notes.Count} note(s)");
    return string.Join("\n---\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

